}
@media (max-width: 600px) {
    .card { width: 150px; height: 225px; }
}

// JavaScript (script.js)
const wrestlers = [
    { name: "John Cena", img: "cena.jpg", finisher: "Attitude Adjustment", brand: "Raw", titles: "16x Champion" },
    { name: "The Rock", img: "rock.jpg", finisher: "Rock Bottom", brand: "SmackDown", titles: "8x Champion" }
];
let cards = [...wrestlers];
function renderCards() {
    const container = document.getElementById("cardContainer");
    container.innerHTML = cards.map((w, i) => `
        <div class="card">
            <div class="card-inner">
                <div class="card-front"><h2>${w.name}</h2><img src="${w.img}" alt="${w.name}" width="100"></div>
                <div class="card-back"><p>Finisher: ${w.finisher}</p><p>Brand: ${w.brand}</p><p>Titles: ${w.titles}</p></div>
            </div>
        </div>
    `).join("");
}
function shuffleCards() {
    cards = cards.sort(() => Math.random() - 0.5);
    renderCards();
}
function showRandomCard() {
    const randomCard = cards[Math.floor(Math.random() * cards.length)];
    cards = [randomCard];
    renderCards();
}
renderCards();

